
import {createScene} from './scene.js';
import * as E from './engine.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₺'+Math.round(n).toLocaleString('tr-TR');
let s=E.initial(),saveProblem='',view='home',speed=1,paused=false,animTimer,timer,toastTimer;
try{const raw=localStorage.getItem(E.KEY);if(raw){const loaded=JSON.parse(raw);if(E.validSave(loaded))s=loaded;else saveProblem='Kayıt okunamadı. Eski kaydın üzerine yazılmadı.'}}catch{saveProblem='Cihaz kaydına erişilemiyor. Bu oturumda oynayabilirsin.'}
let scene;try{scene=createScene($('scene'))}catch{scene={set(){},rotate(){}};$('scene').innerHTML='<p class="notice">3B görüntü başlatılamadı. Safari’yi güncelleyip sayfayı yeniden açmayı dene.</p>'}
const icons={home:'<path d="M12 3 3 10v11h6v-7h6v7h6V10Z"/>',train:'<path d="M3 8v8m4-11v14m10-14v14m4-11v8M7 12h10"/>',fight:'<path d="M8 3h8l5 5v8l-5 5H8l-5-5V8Zm1 5 6 8m0-8-6 8"/>',gym:'<path d="M3 21V7l9-4 9 4v14M1 21h22M9 21v-6h6v6M7 8v3m5-3v3m5-3v3"/>',career:'<path d="M7 3h10v5a5 5 0 0 1-10 0ZM7 5H3v3a5 5 0 0 0 5 5M17 5h4v3a5 5 0 0 1-5 5M12 13v7m-5 1h10"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.train}</svg>`;
const btn=(text,act,value='',cls='',disabled=false)=>`<button class="${cls}" data-action="${act}" data-value="${value}" ${disabled?'disabled':''}>${text}</button>`;
const section=(title,note='')=>`<div class="section-head"><h2>${title}</h2><span>${note}</span></div>`;
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200)}
function runTimer(){clearInterval(timer);if(!paused&&s.fight&&!s.fight.done)timer=setInterval(()=>{if(document.hidden)return;E.stepFight(s);save();updateFight()},800/speed)}
function act(action,value){try{let msg='';if(action==='nav'){navigate(value);return}if(action==='train'||action==='move'){const m=action==='move'?E.MOVES.find(m=>m.id===value):null,key=m?m.skill:value;msg=E.train(s,key,m?.id);save();render();scene.set({mode:'train',move:key==='stamina'?'run':key});clearTimeout(animTimer);animTimer=setTimeout(()=>{if(!s.fight||s.fight.done)scene.set({mode:'home'})},2200);toast(msg);return}if(action==='recover')msg=E.recover(s,value);if(action==='gym')msg=E.chooseGym(s,Number(value));if(action==='coach')msg=E.chooseCoach(s,Number(value));if(action==='start'){E.startFight(s,Number(value));view='fight';paused=false;save();render();runTimer();window.scrollTo({top:0,behavior:'smooth'});return}if(action==='tactic'){E.tactic(s,value);save();updateFight();return}if(action==='pause'){paused=!paused;runTimer();fightPage();return}if(action==='speed'){speed=speed===1?2:speed===2?4:1;runTimer();fightPage();return}if(action==='skip'){while(s.fight&&!s.fight.done)E.stepFight(s);save();updateFight();return}if(action==='finish'){s.fight=null;view='career';save();render();return}if(action==='close'){$('modal').close();return}if(action==='name'){const n=$('fighter-name').value.trim();if(!n||n.length>24)throw Error('1–24 karakter arasında bir isim yaz.');s.name=n;save();$('modal').close();render();toast('İsmin güncellendi.');return}if(action==='export'){const u=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='cage-kariyer-'+E.day(s)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return}if(action==='reset'){$('modal').innerHTML=`<h2>Yeni bir hikâye?</h2><p>Mevcut kariyerin sıfırlanacak. Saklamak istiyorsan önce kaydını dışa aktar.</p><div class="buttons">${btn('Vazgeç','close')}${btn('Yeni kariyere başla','reset-confirm','','primary')}</div>`;return}if(action==='reset-confirm'){try{localStorage.setItem('cage-backup-v1',localStorage.getItem(E.KEY)||'')}catch{}s=E.initial();saveProblem='';view='home';clearInterval(timer);$('modal').close();msg='Yeni kariyer başladı.'}save();render();if(msg)toast(msg)}catch(e){toast(e.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)act(b.dataset.action,b.dataset.value)});
$('rotate').onclick=()=>scene.rotate();
$('settings').onclick=()=>{$('modal').innerHTML=`<h2>Kariyerin, senin kontrolünde.</h2><p>İlerlemen bu tarayıcıda saklanır. Cihaz değiştirirken kaydını dışa aktar. Safari verilerini temizlersen kayıt da silinir.</p><label for="fighter-name">Dövüşçünün adı</label><input id="fighter-name" maxlength="24" value="${esc(s.name)}" autocomplete="off"><div class="buttons">${btn('Adı kaydet','name','','primary')}${btn('Kapat','close')}</div><div class="divider" style="margin:22px 0"></div><div class="inline-actions">${btn('Kaydı dışa aktar','export')}${btn('Yeni kariyer','reset')}</div><label for="import-save">Kayıt dosyasından devam et</label><input id="import-save" type="file" accept=".json,application/json"><p>iPhone: Safari’nin Paylaş menüsünden Ana Ekrana Ekle. Bu sürüm internet bağlantısı ile oynanır.</p>`;$('modal').showModal();$('import-save').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>150000)throw Error('Kayıt dosyası çok büyük.');const next=JSON.parse(await file.text());if(!E.validSave(next))throw Error('Geçerli bir CAGE kaydı değil.');$('modal').innerHTML=`<h2>Bu kariyere dön?</h2><p>${esc(next.name)} · ${next.wins} galibiyet · ${money(next.cash)}<br>Mevcut ilerlemenin yerine bu dosya açılacak.</p><div class="buttons"><button id="import-confirm" class="primary">Kaydı aç</button>${btn('Vazgeç','close')}</div>`;$('import-confirm').onclick=()=>{clearInterval(timer);s=next;saveProblem='';view=s.fight?'fight':'home';save();$('modal').close();render();runTimer();toast('Kariyer yüklendi.')}}catch(err){toast(err.message)}}};
function save(){if(saveProblem)return;try{localStorage.setItem(E.KEY,JSON.stringify(s));$('save-status').textContent='Bu cihazda kaydedildi · '+E.day(s)+'. gün'}catch{saveProblem='Kayıt yapılamadı; Ayarlar’dan ilerlemeni dışa aktar.';$('save-status').textContent=saveProblem;toast(saveProblem)}}
function skillRows(){return `<div class="stats-grid">${Object.entries(E.LABELS).map(([k,n])=>`<div class="skill-row"><div class="row"><span>${n}</span><b>${Math.floor(s.skills[k])}<span class="muted"> / 100</span></b></div><div class="bar"><i style="width:${s.skills[k]}%"></i></div></div>`).join('')}</div>`}
function navigate(next){if(s.fight&&!s.fight.done&&next!=='fight'){toast('Maç sürüyor. Taktik ver veya sonucu gör.');return}view=next;render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){document.body.classList.toggle('is-fighting',view==='fight'&&!!s.fight);const l=E.league(s);$('navigation').innerHTML=[['home','Dövüşçüm'],['train','Antrenman'],['fight','Dövüş'],['gym','Gym & Ekip'],['career','Kariyer']].map(([k,n])=>`<button class="${view===k?'active':''}" data-action="nav" data-value="${k}" ${view===k?'aria-current="page"':''}>${icon(k)}<span>${n}</span></button>`).join('');$('cash').textContent=money(s.cash);$('date').innerHTML=`${E.day(s)}. gün <span>${String(Math.floor(s.hours%24)).padStart(2,'0')}:${s.hours%1?'30':'00'}</span>`;$('vitals').innerHTML=[['energy','Enerji'],['food','Tokluk'],['sleep','Dinçlik'],['health','Sağlık']].map(([k,n])=>`<div class="vital"><div class="vital-head"><span>${n}</span><b>${Math.round(s[k])}</b></div><div class="bar" role="meter" aria-label="${n}" aria-valuenow="${Math.round(s[k])}" aria-valuemin="0" aria-valuemax="100"><i style="width:${s[k]}%"></i></div></div>`).join('');$('chapter').textContent=`BÖLÜM 0${l+1} / ${['BAŞLANGIÇ','ADINI DUYUR','BÜYÜK SAHNE','ZİRVE'][l]}`;$('rank-badge').textContent=E.LEAGUES[l].name.toLocaleUpperCase('tr-TR');$('page-title').innerHTML={home:'Her efsane <em>bir yerden başlar.</em>',train:'Tekrar. Disiplin. <em>Gelişim.</em>',fight:'Söz bitti. <em>Sıra kafeste.</em>',gym:'Doğru yer. <em>Doğru ekip.</em>',career:'Sokaktan <em>zirveye.</em>'}[view];$('scene-label').textContent=E.GYMS[s.gym].name.toLocaleUpperCase('tr-TR')+' / ANTRENMAN';$('fighter-caption').innerHTML=`<div><span class="eyebrow">${['YOLUN BAŞINDASIN','ADIN DUYULUYOR','PROFESYONEL DÖVÜŞÇÜ','ZİRVEYE BİR ADIM'][l]}</span><h2>${esc(s.name)}</h2><span>${s.wins} galibiyet · ${s.losses} mağlubiyet</span></div><div class="weight"><strong>${(68+s.skills.strength*.17).toFixed(1)}</strong><span>KG</span></div>`;$('stage-layout').classList.toggle('fight-stage',view==='fight'&&!!s.fight);$('fight-hud').innerHTML='';$('fight-overlay').innerHTML='';scene.set({mode:'home',gym:s.gym,strength:s.skills.strength,phase:'stand'});if(saveProblem)$('save-status').textContent=saveProblem;({home,train:training,gym:gyms,career,fight:fightPage}[view])();}
function home(){const next=E.LEAGUES[E.league(s)+1];$('context').innerHTML=`<span class="eyebrow">DÖVÜŞÇÜ KARTI</span><h2>${esc(s.name)}</h2><div class="row"><div class="metric"><strong>${s.wins}–${s.losses}</strong>Maç karnesi</div><div class="metric"><strong>${s.sessions}</strong>Antrenman</div><div class="metric"><strong>${Math.floor(s.skills.strength)}</strong>Kuvvet</div></div><div class="divider"></div><p>${next?`${next.name} için ${Math.max(0,next.min-s.wins)} galibiyet daha.`:'Dünya liginde 20. galibiyetinden itibaren şampiyonluk senin.'}</p>${btn('Antrenmana başla','nav','train','primary')}${btn('Dövüş bul','nav','fight','ghost')}`;$('content').innerHTML=section('İyi dövüşçü önce kendine bakar.','GÜN '+E.day(s))+'<div class="cards">'+recoveryCard('Sıcak bir öğün','Tokluk +45 · Enerji +5','30 dk · ₺35','Yemek ye','meal')+recoveryCard('Bir gece, yeni bir sen','Enerji +75 · Dinçlik +90 · Sağlık +32','8 saat · Tokluk −14','Uyu','sleep')+recoveryCard('Nefes al','Enerji +30 · Sağlık +14','2 saat · Tokluk −5','Dinlen','rest')+'</div>'+section('Dövüş DNA’n','HER DAL AYRI GELİŞİR')+`<div class="card">${skillRows()}</div>`+section('Küçük adımlar, büyük hayaller.')+'<div class="cards">'+recoveryCard('Gündelik iş','Antrenman masrafını çıkar. Enerji −15.','3 saat · +₺110','İşe git','job')+recoveryCard('Mahalle mutfağı','Günde bir ücretsiz yemek. Tokluk +55.','Ücretsiz','Yemek al','help',s.helpDay===E.day(s))+recoveryCard('Sporcu tabağı','Tokluk +70 · Enerji +12 · Sağlık +8','30 dk · ₺80','Beslen','protein')+'</div>'+(s.sessions===0?'<div class="notice">İlk hedefin: birkaç antrenman yap, yemek ye ve dinlen. Sonra ilk maçını seç. İhtiyaçların yalnız oynarken azalır.</div>':'');}
function recoveryCard(title,desc,cost,label,action,disabled=false){return `<article class="card"><h3>${title}</h3><p>${desc}</p><span class="cost">${cost}</span>${btn(label,'recover',action,'',disabled)}</article>`}
function gyms(){$('context').innerHTML=`<span class="eyebrow">MEVCUT SALONUN</span><h2>${E.GYMS[s.gym].name}</h2><p>Üyeliği bir kez alırsın. Her antrenmanda seans ücretini ödersin. Koşu ve ip atlama ücretsiz.</p><div class="divider"></div><p>Evine ücretsiz dönebilirsin. Kazandığın üyelikler sende kalır.</p>${btn('Antrenmana dön','nav','train','primary')}`;$('content').innerHTML=section('Bir sonraki seviyen.','4 ANTRENMAN ALANI')+`<div class="cards">${E.GYMS.map((g,i)=>`<article class="card"><span class="eyebrow">0${i+1} / ${s.gym===i?'MEVCUT':s.ownedGyms.includes(i)?'ÜYESİN':'YENİ SALON'}</span><h3>${g.name}</h3><p>${g.sub} Gelişim ×${g.gain.toFixed(1)}.</p><span class="cost">Üyelik ${money(g.price)}<br>Seans ${money(g.fee)}${g.wins?` · ${g.wins} galibiyet`:''}</span>${btn(s.gym===i?'Burada çalışıyorsun':s.ownedGyms.includes(i)?'Buraya geç':'Üyelik al','gym',i,'',s.gym===i||s.wins<g.wins)}</article>`).join('')}</div>`+section('Köşende kim var?','1 AKTİF ANTRENÖR')+`<div class="cards">${E.COACHES.slice(1).map((c,j)=>{const i=j+1;return `<article class="card"><div class="card-top"><span class="card-icon">${icon('gym')}</span><span class="tag">+%${Math.round(c.bonus*100)}</span></div><h3>${c.name}</h3><p>${E.LABELS[c.skill]} gelişimini hızlandırır. Yalnız kendi dalındaki seanslarda ücret alır.</p><span class="cost">Anlaşma ${money(c.price)}<br>İlgili seans ${money(c.fee)}</span>${btn(s.coach===i?'Köşende':s.ownedCoaches.includes(i)?'Birlikte çalış':'Anlaşma yap','coach',i,'',s.coach===i)}</article>`}).join('')}</div>`+(s.coach?`<div class="inline-actions" style="margin-top:16px">${btn('Antrenörsüz çalış','coach',0,'ghost')}</div>`:'');}
function career(){const l=E.league(s);$('context').innerHTML=`<span class="eyebrow">KARİYER ÖZETİ</span><h2>${s.wins>=20?'Zirveden bak.':'Bu senin hikâyen.'}</h2><div class="row"><div class="metric"><strong>${s.wins}–${s.losses}</strong>Galibiyet / mağlubiyet</div><div class="metric"><strong>${s.sessions}</strong>Seans</div></div><div class="divider"></div><div class="metric"><strong>${money(s.earned)}</strong>Toplam kariyer kazancı</div><p>İlk para, ilk zafer, ilk büyük sözleşme. Her adım emek istiyor.</p>${btn('Yeni bir maça hazırlan','nav','fight','primary')}`;$('content').innerHTML=section('Şampiyonluk yolu','GALİBİYETLERLE YÜKSEL')+`<div class="league-track">${E.LEAGUES.map((g,i)=>`<div class="league-step ${l===i?'current':l>i?'done':''}"><span class="eyebrow">0${i+1} / ${l>=i?'AÇIK':'KİLİTLİ'}</span><h3>${g.name}</h3><p>${g.min} galibiyet<br>Zafer ${money(g.purse)}</p></div>`).join('')}</div>`+section('Maç geçmişi',s.history.length+' MAÇ')+(s.history.length?s.history.map(h=>`<div class="record"><div><b>${esc(h.name)}</b><p>${h.day}. gün · ${E.LEAGUES[h.tier]?.name||''} · ${esc(h.method)}</p></div><div style="text-align:right"><b class="${h.won?'win':'loss'}">${h.draw?'BERABERE':h.won?'GALİBİYET':'MAĞLUBİYET'}</b><p>${money(h.reward)}</p></div></div>`).join(''):'<div class="empty">Henüz ringe çıkmadın.<br>İlk maç, hikâyenin ilk sayfası.</div>');}
function fightPage(){const f=s.fight;if(!f){const l=E.league(s),o=E.opponent(s);$('context').innerHTML=`<span class="eyebrow">SIRADAKİ RAKİBİN</span><h2>${esc(o.name)}</h2><p>${E.LABELS[o.style]} ağırlıklı dövüşür. ${['boxing','kickboxing'].includes(o.style)?'Yere almayı veya kontrollü savunmayı dene.':'Ayakta mesafeyi korumayı dene.'}</p><div class="row"><div class="metric"><strong>${Math.floor(o.skills[o.style])}</strong>${E.LABELS[o.style]}</div><div class="metric"><strong>${money(E.LEAGUES[l].purse)}</strong>Zafer ödülü</div></div><p>Maçı izle, köşeden taktik ver. Mağlubiyette de katılım payı alırsın.</p>${btn('Kafese gir','start',l,'primary')}`;$('content').innerHTML=section('Dövüş kartları','GİRİŞ ÜCRETSİZ')+`<div class="cards">${E.LEAGUES.map((g,i)=>`<article class="card"><span class="eyebrow">${i<=l?'KATILABİLİRSİN':g.min+' GALİBİYET GEREKLİ'}</span><h3>${g.name}</h3><p>${g.venue.toLocaleLowerCase('tr-TR')}<br>Rakip seviyesi yaklaşık ${g.base}–${g.base+11}.</p><span class="cost">Zafer ${money(g.purse)}<br>Katılım payı ${money(g.loss)}</span>${btn('Bu ligde dövüş','start',i,'',i>l)}</article>`).join('')}</div><div class="notice">Maç için: en az 35 enerji, 25 tokluk, 25 dinçlik ve 50 sağlık. Açık olan alt liglerde de dövüşebilirsin.</div>`;return}
 $('scene-label').textContent=E.LEAGUES[f.tier].venue;$('context').innerHTML=`<span class="eyebrow">KÖŞEDEN YÖNET</span><h2>Oyun planın.</h2><p id="tactic-description"></p><div class="tactics">${[['balanced','Dengeli'],['strike','Ayakta baskı'],['ground','Yere al'],['defend','Savun & dinlen']].map(([k,n])=>btn(n,'tactic',k,'',f.done)).join('')}</div><div class="fight-log" id="fight-log" aria-live="polite"></div><div class="fight-controls">${btn(paused?'Devam':'Duraklat','pause','','',f.done)}${btn('Hız '+speed+'×','speed','','',f.done)}</div>${btn('Sonucu gör','skip','','ghost',f.done)}`;$('content').innerHTML=section('Köşenin notları')+'<div class="notice">Ayakta baskı daha sert vurur ama daha çok dayanıklılık harcar. Yere al taktiği güreşini ve BJJ’ni kullanır. Savun & dinlen darbeleri azaltır, nefes toplatır. Maç içi dayanıklılık, günlük enerjinden ayrıdır.</div>';updateFight();}
function updateFight(){const f=s.fight;if(!f||view!=='fight')return;scene.set({mode:'fight',phase:f.phase,move:f.last.move,attacker:f.last.attacker,pulse:1});const remain=180-(f.tick%20)*9;$('fight-hud').innerHTML=`<div class="fight-head">${[0,1].map(i=>`${i===1?`<div class="round">RAUND ${Math.min(3,Math.floor(f.tick/20)+1)} / 3<strong>${f.done?'BİTTİ':Math.floor(remain/60)+':'+String(remain%60).padStart(2,'0')}</strong>${f.phase==='ground'?'YERDE':'AYAKTA'}</div>`:''}<div class="fight-person"><strong>${esc(i?s.fight.enemy.name:s.name)}</strong><div class="bar"><i style="width:${E.clamp(f.hp[i]/f.maxHp[i]*100)}%"></i></div><small>Can ${Math.max(0,Math.ceil(f.hp[i]))} · Dayanıklılık ${Math.round(f.st[i]/f.maxSt[i]*100)}%</small></div>`).join('')}</div>`;$('fight-log').textContent=f.log;$('tactic-description').textContent={balanced:'Tekniklerine güven. Fırsat buldukça hücum et.',strike:'Mesafeyi koru. Daha sert vur, ayakta kal.',ground:'Güreşle yere indir. BJJ ile kontrol et.',defend:'Gardı kapat. Nefes topla, darbeleri azalt.'}[f.tactic];document.querySelectorAll('[data-action="tactic"]').forEach(b=>{b.classList.toggle('active',b.dataset.value===f.tactic);b.setAttribute('aria-pressed',String(b.dataset.value===f.tactic))});if(f.done){clearInterval(timer);const r=f.result;$('fight-overlay').innerHTML=`<div class="result"><div><span class="eyebrow">${E.LEAGUES[f.tier].name.toLocaleUpperCase('tr-TR')} / ${r.method.toLocaleUpperCase('tr-TR')}</span><h2 style="color:${r.winner===1?'var(--orange)':'var(--lime)'}">${r.champion?'ŞAMPİYON!':r.winner===0?'ZAFER SENİN.':r.winner===2?'BERABERE.':'BU DA BİR DERS.'}</h2><p>${r.winner===0?'Sıkı çalışmanın karşılığını aldın.':r.winner===2?'Bu gece birbirinize üstünlük kuramadınız.':'Toparlan, eksiklerini çalış, yeniden gel.'}<br><strong>+${money(r.reward)}</strong>${r.promotion?'<br>Yeni lig açıldı: '+E.LEAGUES[E.league(s)].name:''}</p>${btn('Kariyerine dön','finish','','primary')}</div></div>`;$('cash').textContent=money(s.cash);document.querySelectorAll('[data-action="tactic"],[data-action="pause"],[data-action="speed"],[data-action="skip"]').forEach(b=>b.disabled=true)}}
const trainings=[['boxing','Gölge boksu','Yumruk isabeti ve ayakta savunma.'],['kickboxing','Tekme çalışması','Mesafe, tekme tekniği ve isabet.'],['wrestling','Güreş temelleri','Yere alma ve dalış savunması.'],['bjj','BJJ çalışması','Yerde kontrol, kaçış ve pes ettirme.'],['stamina','Mahalle koşusu','Maçta dayanıklılık ve toparlanma.'],['rope','İp atlama','Ritim, ayak oyunu ve kondisyon.'],['strength','Kuvvet antrenmanı','Daha güçlü darbeler, daha kaslı bir vücut.']];
function training(){const g=E.GYMS[s.gym];$('context').innerHTML=`<span class="eyebrow">BUGÜNKÜ ANTRENMAN ALANIN</span><h2>${g.name}</h2><p>${g.sub}</p><div class="row"><div class="metric"><strong>×${g.gain.toFixed(1)}</strong>Gelişim</div><div class="metric"><strong>${money(g.fee)}</strong>Seans ücreti</div></div><div class="divider"></div><p>${s.coach?`${E.COACHES[s.coach].name} · ${E.LABELS[E.COACHES[s.coach].skill]} +%${Math.round(E.COACHES[s.coach].bonus*100)}`:'Şu an kendi başına çalışıyorsun.'}</p>${btn('Gym ve antrenörleri gör','nav','gym','primary')}`;$('content').innerHTML=section('Bugün ne çalışıyoruz?','1 SAAT / SEANS')+`<div class="cards">${trainings.map(([k,n,d])=>`<article class="card"><div class="card-top"><span class="card-icon">${icon('train')}</span><small>SEVİYE ${Math.floor(s.skills[k==='rope'?'stamina':k])}</small></div><h3>${s.gym>0&&k==='boxing'?'Boks torbası':s.gym>0&&k==='strength'?'Ağırlık antrenmanı':s.gym===0&&k==='strength'?'Vücut ağırlığı':n}</h3><p>${d}</p><span class="cost">${money(E.trainingCost(s,k))} · −18 enerji · −11 tokluk</span>${btn('Çalış','train',k,'',s.skills[k==='rope'?'stamina':k]>=100)}</article>`).join('')}</div>`+section('Teknik defteri','2 ÇALIŞMA İLE ÖĞREN')+`<div class="cards">${E.MOVES.map(m=>{const p=s.moves[m.id]||0,r=s.skills[m.skill]>=m.level;return `<article class="card"><div class="card-top"><span class="tag">${E.LABELS[m.skill]}</span><small>${p===2?'ÖĞRENİLDİ':r?'AÇIK':'KİLİTLİ'}</small></div><h3>${m.name}</h3><p>${p===2?'Maçta uygun pozisyonda otomatik kullanılır.':`${E.LABELS[m.skill]} ${m.level} seviye · ${p}/2 çalışma`}</p>${btn(p===2?'Öğrenildi':r?'Hareketi çalış':'Seviye '+m.level+' gerekli','move',m.id,'',!r||p===2)}</article>`}).join('')}</div>`;}
if(s.fight)view='fight';render();runTimer();if(saveProblem)toast(saveProblem);
const mc=document.modelContext;if(mc?.registerTool){const life=new AbortController();const webTools=[{name:'read_mma_career',description:'Read the current device-local MMA career and active fight.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({name:s.name,cash:s.cash,day:E.day(s),skills:{...s.skills},wins:s.wins,energy:s.energy,food:s.food,sleep:s.sleep,health:s.health,activeFight:!!s.fight&&!s.fight.done})},{name:'train_mma_skill',description:'Complete one training session, spending in-game time, energy and the displayed in-game fee; saves the career.',inputSchema:{type:'object',properties:{skill:{type:'string',enum:[...Object.keys(E.LABELS),'rope']}},required:['skill'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.skill!=='string'||Object.keys(input).some(k=>k!=='skill'))throw Error('A skill is required.');const message=E.train(s,input.skill);save();render();toast(message);return{message,skills:{...s.skills},cash:s.cash}}}];for(const tool of webTools)try{Promise.resolve(mc.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true})}
